import pytest
from collections import Counter
from hypothesis import given, settings, strategies as st
import string

from candidate import task_func

@settings(max_examples=50, deadline=None)
@given(input_str=st.just("Hello, World!"))
def test_example_from_problem(input_str):
    """
    SPEC BASIS: Examples: >>> task_func("Hello, World!") Counter({'l': 3, 'o': 2, 'h': 1, 'e': 1, 'w': 1, 'r': 1, 'd': 1})
    PROPERTY: The function correctly processes the provided example input and produces the expected output.
    """
    expected_output = Counter({'l': 3, 'o': 2, 'h': 1, 'e': 1, 'w': 1, 'r': 1, 'd': 1})
    assert task_func(input_str) == expected_output

@settings(max_examples=50, deadline=None)
@given(
    alphanum_chars=st.lists(
        st.one_of(st.characters(whitelist_categories=('Lu', 'Ll', 'Nd')), st.just('')),
        min_size=0, max_size=10
    ),
    special_chars=st.lists(
        st.characters(blacklist_categories=('Lu', 'Ll', 'Nd'), min_codepoint=32, max_codepoint=126),
        min_size=0, max_size=10
    )
)
def test_alphanumeric_and_case_invariance(alphanum_chars, special_chars):
    """
    SPEC BASIS: "Count the frequency of each alphanumeric character in a given string after removing all non-alphanumeric characters, treating uppercase and lowercase letters as the same."
    PROPERTY: Adding non-alphanumeric characters or changing case of alphanumeric characters does not alter the final lowercase character counts.
    """
    # Build an input string by interleaving alphanumeric and special characters
    input_parts = []
    for i in range(max(len(alphanum_chars), len(special_chars))):
        if i < len(alphanum_chars):
            input_parts.append(alphanum_chars[i])
        if i < len(special_chars):
            input_parts.append(special_chars[i])
    input_str = "".join(input_parts)

    # Manually calculate the expected output
    expected_counter = Counter()
    for char_str in alphanum_chars:
        if char_str.isalnum(): # Ensure it's actually alphanumeric, as st.just('') might be in alphanum_chars
            expected_counter[char_str.lower()] += 1

    assert task_func(input_str) == expected_counter

@settings(max_examples=50, deadline=None)
@given(
    input_str=st.text(
        alphabet=st.characters(blacklist_categories=('Lu', 'Ll', 'Nd'), min_codepoint=32, max_codepoint=126),
        min_size=0, max_size=12
    )
)
def test_empty_or_special_char_input(input_str):
    """
    SPEC BASIS: "Count the frequency of each alphanumeric character in a given string after removing all non-alphanumeric characters..." (implies no alphanumeric chars means empty count).
    PROPERTY: If the input string contains no alphanumeric characters, the result is an empty dictionary.
    """
    assert task_func(input_str) == Counter()

@settings(max_examples=50, deadline=None)
@given(
    s1=st.text(
        alphabet=st.characters(whitelist_categories=('Lu', 'Ll', 'Nd', 'Zs', 'Po'), min_codepoint=32, max_codepoint=126),
        min_size=0, max_size=6
    ),
    s2=st.text(
        alphabet=st.characters(whitelist_categories=('Lu', 'Ll', 'Nd', 'Zs', 'Po'), min_codepoint=32, max_codepoint=126),
        min_size=0, max_size=6
    )
)
def test_additive_property_of_concatenation(s1, s2):
    """
    SPEC BASIS: "Count the frequency of each alphanumeric character..." (implies counts should combine).
    PROPERTY: The character counts for a concatenated string are the sum of the counts for the individual strings.
    """
    result1 = task_func(s1)
    result2 = task_func(s2)
    result_combined = task_func(s1 + s2)

    # Counter objects support addition
    assert Counter(result_combined) == Counter(result1) + Counter(result2)

